import {ema,sma,macd,closes} from './indicators.mjs';
const $=id=>document.getElementById(id), keys=['ema','ma','week','month'],labels=['Giá > EMA200 ngày','Giá > MA200 ngày','MACD tuần > 0','MACD tháng > 0'];
const stable=new Set('USDC FDUSD TUSD USDP DAI USDD USD1 USTC BUSD USDE USDS AEUR EURI RLUSD BFUSD'.split(' '));
let data=[],filter='all',total=0,completed=0,running=false,limited=false;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function api(path){for(let attempt=0;attempt<3;attempt++){if(limited)throw Error('Binance giới hạn truy cập');try{const response=await fetch('https://data-api.binance.vision/api/v3/'+path,{signal:AbortSignal.timeout(20000)});if(response.status===429||response.status===418){limited=true;throw Error('Binance giới hạn tốc độ (HTTP '+response.status+'). Vui lòng đợi vài phút rồi thử lại.')}if(!response.ok)throw Error('Binance HTTP '+response.status);return await response.json()}catch(e){if(limited||attempt===2)throw e;await sleep(1000*(attempt+1))}}}
function number(v){return v==null?'—':v.toLocaleString('en-US',{maximumSignificantDigits:7})}
function qualifies(r,key){return r[key]!=null&&(key==='ema'||key==='ma'?r.price>r[key]:r[key]>0)}
function render(){
 $('cards').innerHTML=keys.map((key,i)=>{const eligible=data.filter(r=>r[key]!=null),count=eligible.filter(r=>qualifies(r,key)).length,pct=eligible.length?count/eligible.length*100:0;return `<article class="card"><div class="top"><span>${labels[i]}</span><span class="index">0${i+1}</span></div><div class="num">${eligible.length?count:'—'}<small>coin</small></div><div class="ratio">${eligible.length?pct.toFixed(1)+'%':'—'} <span class="na">/ ${eligible.length} đủ dữ liệu</span></div><div class="track"><div class="fill" style="width:${pct}%"></div></div><div class="caption">${running?'Đang quét · kết quả một phần':data.length?'Kết quả lượt quét gần nhất':'Chưa có dữ liệu'} · ${data.filter(r=>!r.error&&r[key]==null).length} thiếu lịch sử</div></article>`}).join('');
 const q=$('search').value.toUpperCase().trim(),visible=data.filter(r=>r.base.toUpperCase().includes(q)&&(filter==='all'||(filter==='error'?r.error:qualifies(r,filter)))).sort((a,b)=>b.volume-a.volume);
 $('rows').replaceChildren();for(const r of visible){const tr=document.createElement('tr'),coin=document.createElement('td'),b=document.createElement('b');b.textContent=r.base;coin.append(b,document.createTextNode(' / USDT'));if(r.error){const hint=document.createElement('small');hint.textContent=' · Lỗi tải';hint.title=r.error;coin.append(hint)}tr.append(coin);const price=document.createElement('td');price.textContent=number(r.price);tr.append(price);for(const key of keys){const td=document.createElement('td');td.textContent=number(r[key]);td.className=r[key]==null?'na':qualifies(r,key)?'positive':'negative';tr.append(td)}$('rows').append(tr)}
 $('empty').style.display=visible.length?'none':'block';$('empty').textContent=data.length?'Không có coin phù hợp bộ lọc.':'Nhấn “Cập nhật dữ liệu” để quét thị trường.';
 $('foot').textContent=`${visible.length} hiển thị · ${completed}/${total} đã xử lý · ${data.filter(r=>r.error).length} coin có lỗi tải`;
 $('bar').style.width=total?(completed/total*100)+'%':'0';
}
async function scan(){if(running)return;running=true;limited=false;data=[];completed=0;total=0;render();$('refresh').disabled=true;$('scope').disabled=$('mode').disabled=$('stable').disabled=true;$('status').textContent='Đang lấy danh sách coin và giá hiện tại…';$('updated').textContent='Đang cập nhật';
 const scope=$('scope').value,live=$('mode').value==='live',exclude=$('stable').checked;
 try{const [info,tickers]=await Promise.all([api('exchangeInfo'),api('ticker/24hr')]);const quotes=new Map(tickers.map(t=>[t.symbol,t]));let symbols=info.symbols.filter(s=>s.status==='TRADING'&&s.quoteAsset==='USDT'&&s.isSpotTradingAllowed!==false&&(!exclude||!stable.has(s.baseAsset))&&quotes.has(s.symbol)).sort((a,b)=>Number(quotes.get(b.symbol).quoteVolume)-Number(quotes.get(a.symbol).quoteVolume));if(scope!=='all')symbols=symbols.slice(0,Number(scope));total=symbols.length;let cursor=0;
 async function worker(){while(cursor<symbols.length&&!limited){const s=symbols[cursor++],t=quotes.get(s.symbol),r={base:s.baseAsset,price:Number(t.lastPrice),volume:Number(t.quoteVolume),ema:null,ma:null,week:null,month:null};const results=await Promise.allSettled([api(`klines?symbol=${encodeURIComponent(s.symbol)}&interval=1d&limit=1000`),api(`klines?symbol=${encodeURIComponent(s.symbol)}&interval=1w&limit=1000`),api(`klines?symbol=${encodeURIComponent(s.symbol)}&interval=1M&limit=1000`)]);const now=Date.now();if(results[0].status==='fulfilled'){const c=closes(results[0].value,false,now);r.ema=ema(c,200);r.ma=sma(c,200)}if(results[1].status==='fulfilled')r.week=macd(closes(results[1].value,live,now));if(results[2].status==='fulfilled')r.month=macd(closes(results[2].value,live,now));const errors=results.filter(v=>v.status==='rejected');if(errors.length)r.error=errors.map(e=>e.reason.message).join('; ');data.push(r);completed++;$('status').textContent=`Đang quét ${completed}/${total} coin · ${s.baseAsset} · Kết quả một phần`;render();await sleep(650)}}
 await Promise.all([worker(),worker()]);$('status').textContent=limited?`Đã dừng do giới hạn Binance. Kết quả một phần: ${completed}/${total} coin.`:`Hoàn tất ${completed}/${total} coin${data.some(r=>r.error)?' · Có lỗi tải, xem bộ lọc Lỗi tải':''}`;$('updated').textContent='Cập nhật '+new Date().toLocaleString('vi-VN');
 }catch(e){$('status').textContent='Không tải được dữ liệu: '+e.message+'. Kiểm tra kết nối và thử lại.';$('updated').textContent='Cập nhật thất bại'}finally{running=false;$('refresh').disabled=false;$('scope').disabled=$('mode').disabled=$('stable').disabled=false;render()}}
$('refresh').addEventListener('click',scan);$('search').addEventListener('input',render);$('filters').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('.filters button').forEach(x=>x.classList.toggle('selected',x===b));render()});render();
